<template><div class="min-h-screen bg-[#fffaf8]"><Navbar /><main class="mx-auto max-w-xl px-4 py-10"><p class="eyebrow">Visitor access</p><h1 class="mt-2 text-4xl font-bold">Register as Visitor</h1><form class="surface mt-8 space-y-4 p-6" @submit.prevent="submit"><label class="block"><span class="form-label">Office</span><select v-model="form.office_id" class="form-input" required><option value="">Choose an office</option><option v-for="office in offices" :value="office.id" :key="office.id">{{ office.office_name }}</option></select></label><label class="block"><span class="form-label">Full name</span><input v-model="form.fullname" class="form-input" required autocomplete="name"></label><label class="block"><span class="form-label">Contact number</span><input v-model="form.contact_number" class="form-input" required inputmode="tel"></label><label class="block"><span class="form-label">Address</span><input v-model="form.address" class="form-input" required></label><label class="block"><span class="form-label">Purpose</span><textarea v-model="form.purpose" class="form-input" rows="2"></textarea></label><p v-if="error" class="text-sm text-red-700">{{ error }}</p><button class="w-full rounded-xl bg-[var(--bsu-red)] px-5 py-3 font-bold text-white">{{ submitting ? "Registering..." : "Register visit" }}</button></form><div v-if="result" class="surface mt-5 p-6"><h2 class="text-xl font-bold">Registration received</h2><p class="mt-2">Your visitor status token is ready.</p><router-link :to="`/status?token=${result.access_token}`" class="mt-4 inline-block font-semibold text-[var(--bsu-red)]">Check status →</router-link></div></main></div></template>
<script setup>
import { onMounted, reactive, ref } from "vue"; import { useRoute } from "vue-router"; import Navbar from "@/components/Navbar.vue";
const route = useRoute(); const API_BASE = import.meta.env.VITE_API_BASE || "/api"; const offices = ref([]); const result = ref(null); const error = ref(""); const submitting = ref(false); const form = reactive({ office_id: route.query.office || "", fullname: "", contact_number: "", address: "", purpose: "" });
onMounted(async () => { const response = await fetch(`${API_BASE}/public/offices`); offices.value = (await response.json()).offices || []; });
async function submit() { submitting.value = true; error.value = ""; try { const response = await fetch(`${API_BASE}/public/register`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Registration failed"); result.value = data; } catch (err) { error.value = err.message; } finally { submitting.value = false; } }
</script>
